10	    let onErrorArgs: {session: ChatSession; error: Error} | undefined;
11	    let afterSessionArg: ChatSession | undefined;
12	    const engine = createHalEngine({
13	      provider: {type: 'mock'},
14	      prompt: {identity: 'test'},
15	      auth: {ws: (async () => null) as unknown as WsAuthenticator},
16	      orchestrator: {
17	        hooks: {
18	          beforeSession: async () => {
19	            order.push('beforeSession');
20	            throw failure;
21	          },
22	          onError: async (session, error) => {
23	            order.push('onError');
24	            onErrorArgs = {session, error};
25	          },
26	          afterSession: async session => {
27	            order.push('afterSession');
28	            afterSessionArg = session;
29	          },
30	        },
31	      },
32	    });
33	    const session: ChatSession = {
34	      sessionId: 'before-session-failure',
35	      userId: 'u1',
36	      entries: [{role: 'user', content: 'hello', timestamp: ''}],
37	    };
38	
39	    await expect(engine.orchestrator.processMessage(session)).rejects.toBe(failure);
40	
41	    expect({order, onErrorArgs, afterSessionArg}).toEqual({
42	      order: ['beforeSession', 'onError', 'afterSession'],
43	      onErrorArgs: {session, error: failure},
44	      afterSessionArg: session,
45	    });
46	  });
